#[verifier::external_trait_specification]
pub trait ExRead {
    type ExternalTraitSpecificationFor: std::io::Read;

    fn read_to_end(
        &mut self,
        buf: &mut std::vec::Vec<u8>,
    ) -> (result: std::io::Result<usize>)
        default_ensures
            old(buf)@.is_prefix_of(final(buf)@),
            result is Ok ==>
                final(buf)@.len() == old(buf)@.len() + result->Ok_0,
    ;
}
